to main:
    let maybe count be ask for a number ""
    if maybe count is nothing:
        stop
    let count be value of maybe count
    repeat count times:
        let line be ask ""
        let stack be ""
        let good be true
        for each bracket in line:
            if bracket is "(" or bracket is "[" or bracket is "{":
                set stack to stack + bracket
            otherwise:
                if length of stack is 0:
                    set good to false
                otherwise:
                    let top be character (length of stack - 1) of stack
                    if bracket is ")" and top is not "(":
                        set good to false
                    if bracket is "]" and top is not "[":
                        set good to false
                    if bracket is "}" and top is not "{":
                        set good to false
                    set stack to characters 0 through (length of stack - 2) of stack
        if length of stack is not 0:
            set good to false
        if good:
            say "valid"
        otherwise:
            say "invalid"

