use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let mut lines = input.lines();
    let n: usize = lines.next().unwrap_or("0").trim().parse().unwrap();
    let mut output = String::new();

    for index in 0..n {
        let line = lines.next().unwrap_or("");
        let mut stack = Vec::new();
        let mut valid = true;

        for bracket in line.chars() {
            match bracket {
                '(' | '[' | '{' => stack.push(bracket),
                ')' => valid = stack.pop() == Some('('),
                ']' => valid = stack.pop() == Some('['),
                '}' => valid = stack.pop() == Some('{'),
                _ => unreachable!(),
            }

            if !valid {
                break;
            }
        }

        if !stack.is_empty() {
            valid = false;
        }

        if index > 0 {
            output.push('\n');
        }
        output.push_str(if valid { "valid" } else { "invalid" });
    }

    if n > 0 {
        output.push('\n');
    }
    print!("{output}");
}

