import sys


def main() -> None:
    lines = sys.stdin.buffer
    count_line = lines.readline()
    if not count_line:
        return

    totals: dict[bytes, int] = {}
    for _ in range(int(count_line)):
        name, change = lines.readline().split()
        totals[name] = totals.get(name, 0) + int(change)

    output = b"".join(
        name + b" " + str(totals[name]).encode() + b"\n"
        for name in sorted(totals)
    )
    sys.stdout.buffer.write(output)


if __name__ == "__main__":
    main()

