use std::collections::BTreeMap;
use std::io::{self, BufRead};

fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();

    let n: usize = lines
        .next()
        .expect("missing item count")
        .expect("failed to read item count")
        .trim()
        .parse()
        .expect("invalid item count");

    let mut totals: BTreeMap<String, i128> = BTreeMap::new();

    for _ in 0..n {
        let line = lines
            .next()
            .expect("missing inventory line")
            .expect("failed to read inventory line");
        let (name, change) = line
            .split_once(' ')
            .expect("inventory line must contain a space");
        let change: i128 = change.parse().expect("invalid quantity change");
        *totals.entry(name.to_owned()).or_insert(0) += change;
    }

    let mut output = String::new();
    for (name, total) in totals {
        output.push_str(&name);
        output.push(' ');
        output.push_str(&total.to_string());
        output.push('\n');
    }
    print!("{output}");
}

